-- Business question: rep performance against target.
SELECT r.rep_name AS rep_name, o.order_month AS order_month, r.monthly_target AS monthly_target, SUM(o.amount) AS revenue, CASE WHEN SUM(o.amount) < r.monthly_target THEN 'Below Target' WHEN SUM(o.amount) >= r.monthly_target AND SUM(o.amount) < 1.1 * r.monthly_target THEN 'On Target' ELSE 'Above Target' END AS performance_tier FROM reps r JOIN customers c ON c.rep_id = r.rep_id JOIN orders o ON o.customer_id = c.customer_id WHERE o.status = 'completed' GROUP BY r.rep_name, o.order_month, r.monthly_target ORDER BY r.rep_name, o.order_month;
